import sys

BERKAS = "bot.py"
HELP_BARU = 'PERINTAH_OWNER = [\n    "tambahfitur",\n    "hapusfitur",\n    "cekenv",\n    "pushgithub",\n    "rapikanrepo",\n    "uploadbot",\n    "refresh",\n    "restart",\n    "setpremium",\n    "hapuspremium",\n    "premiumlist",\n    "pricelistset",\n    "pricelistdel",\n    "kantor",\n    "staf",\n    "pecat",\n    "usulan",\n    "laporan",\n    "jadwal",\n    "batalkanjadwal",\n]\nKATEGORI_OWNER = "Khusus Owner"\n\nHELP_KATEGORI = {\n    "Umum dan Info Bot": [\n        ("help", "Lihat semua fitur dan perintah bot"),\n        ("ping", "Cek apakah bot aktif"),\n        ("stats", "Lihat statistik bot"),\n        ("pricelist", "Lihat paket dan harga premium bot ini"),\n        ("premiumstatus", "Cek status premium server ini"),\n    ],\n    "Media dan Musik": [\n        ("download", "Download video atau audio dari link atau judul"),\n        ("spotify", "Ubah link lagu Spotify jadi MP3"),\n        ("tambahid", "Tambah ID lagu ke daftar"),\n        ("hapusid", "Hapus ID lagu dari daftar"),\n        ("id", "Lihat semua ID lagu yang tersimpan"),\n        ("pilihid", "Pilih satu lagu untuk menyalin ID-nya saja"),\n    ],\n    "Chat AI dan Pengingat": [\n        ("chat", "Mulai sesi ngobrol dengan AI di channel ini"),\n        ("endchat", "Hentikan sesi chat AI dan hapus riwayatnya"),\n        ("ingatkan", "Buat pengingat WIB, bisa pakai tanggal dan gambar"),\n        ("listingat", "Lihat pengingat server ini, atau pengingat pribadi di DM"),\n        ("hapusingat", "Hapus pengingat berdasarkan ID"),\n    ],\n    "Pengaturan Server dan Moderasi": [\n        ("setup", "Buat struktur channel dan role (admin, premium)"),\n        ("hapussetup", "Hapus channel dan role buatan setup (admin, premium)"),\n        ("gayanama", "Ubah gaya nama channel buatan setup (admin, premium)"),\n        ("pengaturan", "Lihat pengaturan bot di server ini (admin)"),\n        ("reset", "Matikan salah satu fitur di server ini (admin)"),\n        ("setwelcome", "Atur pesan sambutan di channel ini (admin)"),\n        ("setbanner", "Atur gambar welcome khusus server ini (admin, premium)"),\n        ("hapusbanner", "Kembalikan welcome ke bawaan bot (admin)"),\n        ("setautorole", "Role otomatis untuk member baru (admin)"),\n        ("setjoinvoice", "Atur voice Join to Create (admin)"),\n        ("colorpanel", "Kirim panel warna nama untuk member (admin)"),\n        ("stickyset", "Pasang pesan sticky di channel ini (admin)"),\n        ("stickyhapus", "Matikan pesan sticky di channel ini (admin)"),\n        ("setlog", "Jadikan channel ini Security Log (admin)"),\n        ("setantispam", "Blokir link dari member baru (admin)"),\n        ("purge", "Hapus banyak pesan sekaligus (moderator)"),\n    ],\n    "Custom Command": [\n        ("addcmd", "Buat custom command teks baru (admin)"),\n        ("delcmd", "Hapus custom command teks (admin)"),\n        ("cc", "Jalankan custom command"),\n    ],\n    "Toko dan Tiket": [\n        ("harga", "Lihat daftar harga"),\n        ("hargaset", "Tambah atau ubah harga item (admin)"),\n        ("hargahapus", "Hapus item dari daftar harga (admin)"),\n        ("tiketpanel", "Kirim panel tiket order dan report (admin, premium)"),\n        ("testi", "Kirim testimoni ke channel ini"),\n    ],\n    KATEGORI_OWNER: [\n        ("tambahfitur", "Minta AI membuat fitur baru"),\n        ("hapusfitur", "Copot fitur buatan AI"),\n        ("cekenv", "Periksa isi .env yang terbaca bot"),\n        ("pushgithub", "Kirim atau perbarui satu file di repo GitHub"),\n        ("rapikanrepo", "Kirim README, requirements, dan gitignore ke repo"),\n        ("uploadbot", "Kirim bot.py ke repo GitHub"),\n        ("refresh", "Muat ulang pengaturan dan fitur tambahan"),\n        ("restart", "Nyalakan ulang bot"),\n        ("setpremium", "Beri status premium ke server"),\n        ("hapuspremium", "Cabut status premium server"),\n        ("premiumlist", "Lihat semua server premium"),\n        ("pricelistset", "Tambah atau ubah paket harga premium"),\n        ("pricelistdel", "Hapus paket harga premium"),\n        ("kantor", "Diskusi tim agen AI dan eksekusi aksi"),\n        ("staf", "Lihat anggota tim agen AI"),\n        ("pecat", "Keluarkan anggota rekrutan tim"),\n        ("usulan", "Lihat usulan fitur dari tim"),\n        ("laporan", "Kirim laporan kantor ke email"),\n        ("jadwal", "Lihat pekerjaan terjadwal"),\n        ("batalkanjadwal", "Batalkan pekerjaan terjadwal"),\n    ],\n}\n\n\ndef perintah_ada(nama):\n  return nama in PERINTAH_OWNER or tree.get_command(nama) is not None\n\n\ndef kategori_help(pemilik):\n  hasil = {}\n  for nama, daftar in HELP_KATEGORI.items():\n    if nama == KATEGORI_OWNER and not pemilik:\n      continue\n    isi = [(cmd, ket) for cmd, ket in daftar if perintah_ada(cmd)]\n    if isi:\n      hasil[nama] = isi\n  return hasil\n\n\ndef embed_help_beranda(kategori):\n  embed = discord.Embed(\n      title="Bantuan RyHanC",\n      description=(\n          "Satu bot untuk membangun dan mengelola server komunitas maupun"\n          " jualan.\\n\\nPilih kategori di menu bawah untuk melihat daftar"\n          " perintahnya."\n      ),\n      color=discord.Color.blurple(),\n  )\n  for nama, daftar in kategori.items():\n    embed.add_field(name=nama, value=f"{len(daftar)} perintah", inline=True)\n  embed.set_footer(text="ryhanc.wtf")\n  return embed\n\n\ndef embed_help_kategori(kategori, nama):\n  isi = "\\n".join(f"**/{cmd}**\\n{ket}" for cmd, ket in kategori[nama])\n  embed = discord.Embed(\n      title=f"Bantuan - {nama}",\n      description=isi[:4000],\n      color=discord.Color.blurple(),\n  )\n  if nama == KATEGORI_OWNER:\n    embed.set_footer(text="Hanya muncul di server pribadi pemilik bot")\n  else:\n    embed.set_footer(\n        text="Perintah bertanda admin hanya terlihat oleh admin server"\n    )\n  return embed\n\n\nclass HelpSelect(discord.ui.Select):\n\n  def __init__(self, kategori):\n    self.kategori = kategori\n    opsi = [\n        discord.SelectOption(\n            label="Beranda",\n            value="__beranda__",\n            description="Kembali ke halaman utama",\n        )\n    ]\n    for nama in kategori:\n      opsi.append(discord.SelectOption(label=nama, value=nama))\n    super().__init__(placeholder="Pilih kategori perintah", options=opsi)\n\n  async def callback(self, interaction: discord.Interaction):\n    pilihan = self.values[0]\n    if pilihan == "__beranda__":\n      embed = embed_help_beranda(self.kategori)\n    else:\n      embed = embed_help_kategori(self.kategori, pilihan)\n    await interaction.response.edit_message(embed=embed, view=self.view)\n\n\nclass HelpView(discord.ui.View):\n\n  def __init__(self, kategori):\n    super().__init__(timeout=180)\n    self.add_item(HelpSelect(kategori))\n\n\n@tree.command(name="help", description="Lihat semua fitur dan perintah bot")\nasync def help_command(interaction: discord.Interaction):\n  kategori = kategori_help(interaction.user.id == PEMILIK_ID)\n  await interaction.response.send_message(\n      embed=embed_help_beranda(kategori),\n      view=HelpView(kategori),\n      ephemeral=True,\n  )\n'
BLOK_BAWAH = 'FOLDER_GAMBAR_INGAT = os.path.join(\n    os.path.dirname(CONFIG_FILE) or ".", "pengingat_gambar"\n)\nos.makedirs(FOLDER_GAMBAR_INGAT, exist_ok=True)\nBATAS_PENGINGAT = 30\nTANPA_PING_PENGINGAT = discord.AllowedMentions(\n    everyone=False, roles=False, users=True\n)\n\n\ndef migrasi_pengingat():\n  lama = data.get("pengingat")\n  pribadi = data.setdefault("pengingat_pribadi", {})\n  if isinstance(lama, dict) and all(isinstance(v, list) for v in lama.values()):\n    return\n  data["pengingat"] = {}\n  if isinstance(lama, list):\n    for p in lama:\n      if not isinstance(p, dict):\n        continue\n      kanal = None\n      try:\n        kanal = client.get_channel(int(p.get("channel_id") or 0))\n      except (TypeError, ValueError):\n        kanal = None\n      guild = getattr(kanal, "guild", None)\n      if guild is not None:\n        p["guild_id"] = guild.id\n        data["pengingat"].setdefault(str(guild.id), []).append(p)\n      else:\n        pribadi.setdefault(str(p.get("user_id")), []).append(p)\n  simpan_data()\n\n\ndef gudang_pengingat(guild_id, user_id):\n  migrasi_pengingat()\n  if guild_id:\n    return data["pengingat"].setdefault(str(guild_id), [])\n  return data["pengingat_pribadi"].setdefault(str(user_id), [])\n\n\ndef waktu_pengingat(p):\n  try:\n    w = datetime.fromisoformat(str(p.get("waktu")))\n  except ValueError:\n    return None\n  if w.tzinfo is None:\n    w = w.replace(tzinfo=ZONA_WIB)\n  return w\n\n\ndef path_gambar_pengingat(p):\n  for kunci in ("gambar", "gambar_path", "file_gambar"):\n    nilai = p.get(kunci)\n    if isinstance(nilai, str) and nilai and os.path.isfile(nilai):\n      return nilai\n  return None\n\n\ndef hapus_gambar_pengingat(p):\n  path = path_gambar_pengingat(p)\n  if path:\n    try:\n      os.remove(path)\n    except OSError:\n      pass\n\n\ndef hitung_waktu_target(jam, menit, tanggal, sekarang):\n  if not tanggal:\n    target = sekarang.replace(hour=jam, minute=menit, second=0, microsecond=0)\n    if target <= sekarang:\n      target += timedelta(days=1)\n    return target, None\n  cocok = re.fullmatch(\n      r"\\s*(\\d{1,2})[-/.](\\d{1,2})(?:[-/.](\\d{4}))?\\s*", tanggal\n  )\n  if not cocok:\n    return None, "Format tanggal salah. Pakai DD-MM atau DD-MM-YYYY, contoh 25-12."\n  hari = int(cocok.group(1))\n  bulan = int(cocok.group(2))\n  tahun = int(cocok.group(3)) if cocok.group(3) else sekarang.year\n  try:\n    target = datetime(tahun, bulan, hari, jam, menit, tzinfo=ZONA_WIB)\n  except ValueError:\n    return None, "Tanggal itu tidak ada di kalender. Periksa lagi hari dan bulannya."\n  if target <= sekarang:\n    if cocok.group(3):\n      return None, "Tanggal dan jam itu sudah lewat. Pilih waktu yang akan datang."\n    try:\n      target = target.replace(year=tahun + 1)\n    except ValueError:\n      return None, "Tanggal itu tidak ada di tahun depan. Tulis tahunnya langsung."\n  return target, None\n\n\nasync def coba_kirim_pengingat(tujuan, teks, path):\n  kwargs = {"allowed_mentions": TANPA_PING_PENGINGAT}\n  if path:\n    kwargs["file"] = discord.File(path)\n  try:\n    await tujuan.send(teks[:2000], **kwargs)\n    return True\n  except Exception:\n    return False\n\n\nasync def kirim_pengingat(p, telat):\n  teks = f"<@{p.get(\'user_id\')}> **Pengingat:** {p.get(\'pesan\', \'\')}"\n  if telat > 300:\n    teks += (\n        f"\\n(terkirim terlambat sekitar {int(telat // 60)} menit karena bot"\n        " sempat mati)"\n    )\n  path = path_gambar_pengingat(p)\n  terkirim = False\n  cid = p.get("channel_id")\n  if cid:\n    tujuan = client.get_channel(int(cid))\n    if tujuan is None:\n      try:\n        tujuan = await client.fetch_channel(int(cid))\n      except Exception:\n        tujuan = None\n    if tujuan is not None:\n      terkirim = await coba_kirim_pengingat(tujuan, teks, path)\n  if not terkirim and p.get("user_id"):\n    try:\n      user = await client.fetch_user(int(p["user_id"]))\n      await coba_kirim_pengingat(user, teks, path)\n    except Exception:\n      pass\n  hapus_gambar_pengingat(p)\n\n\nasync def jalankan_pengingat_jatuh_tempo():\n  migrasi_pengingat()\n  sekarang = datetime.now(ZONA_WIB)\n  semua = list(data["pengingat"].values()) + list(\n      data["pengingat_pribadi"].values()\n  )\n  for daftar in semua:\n    for p in list(daftar):\n      w = waktu_pengingat(p)\n      if w is None:\n        daftar.remove(p)\n        simpan_data()\n        continue\n      if w > sekarang:\n        continue\n      daftar.remove(p)\n      simpan_data()\n      await kirim_pengingat(p, (sekarang - w).total_seconds())\n\n\nasync def loop_pengingat():\n  await client.wait_until_ready()\n  while not client.is_closed():\n    try:\n      await jalankan_pengingat_jatuh_tempo()\n    except Exception as e:\n      print(f"Pengingat error: {bersihkan_error(e)}")\n    await asyncio.sleep(15)\n\n\n@tree.command(\n    name="ingatkan",\n    description="Buat pengingat WIB, bisa pakai tanggal dan gambar",\n)\n@app_commands.describe(\n    jam="Jam 0 sampai 23 (WIB)",\n    menit="Menit 0 sampai 59",\n    pesan="Isi pengingat",\n    tanggal="Opsional, format DD-MM atau DD-MM-YYYY",\n    gambar="Opsional, gambar yang ikut dikirim saat pengingat berbunyi",\n)\nasync def ingatkan(\n    interaction: discord.Interaction,\n    jam: app_commands.Range[int, 0, 23],\n    menit: app_commands.Range[int, 0, 59],\n    pesan: str,\n    tanggal: str = None,\n    gambar: discord.Attachment = None,\n):\n  if gambar is not None:\n    if not gambar.content_type or not gambar.content_type.startswith("image/"):\n      await interaction.response.send_message(\n          "Lampiran harus berupa gambar.", ephemeral=True\n      )\n      return\n    if gambar.size > 8 * 1024 * 1024:\n      await interaction.response.send_message(\n          "Ukuran gambar maksimal 8 MB.", ephemeral=True\n      )\n      return\n  daftar = gudang_pengingat(interaction.guild_id, interaction.user.id)\n  if len(daftar) >= BATAS_PENGINGAT:\n    tempat = "server ini" if interaction.guild_id else "pengingat pribadimu"\n    await interaction.response.send_message(\n        f"Batas {BATAS_PENGINGAT} pengingat untuk {tempat} sudah tercapai."\n        " Hapus yang lama dulu dengan /hapusingat.",\n        ephemeral=True,\n    )\n    return\n  sekarang = datetime.now(ZONA_WIB)\n  target, masalah = hitung_waktu_target(jam, menit, tanggal, sekarang)\n  if masalah:\n    await interaction.response.send_message(masalah, ephemeral=True)\n    return\n  await interaction.response.defer(ephemeral=True)\n  dipakai = {p.get("id") for p in daftar}\n  nomor = random.randint(100000, 999999)\n  while nomor in dipakai:\n    nomor = random.randint(100000, 999999)\n  path = None\n  if gambar is not None:\n    aman = re.sub(r"[^A-Za-z0-9._-]", "", gambar.filename)[-40:] or "gambar.png"\n    path = os.path.join(FOLDER_GAMBAR_INGAT, f"{nomor}_{aman}")\n    try:\n      await gambar.save(path)\n    except Exception as e:\n      await interaction.followup.send(\n          f"Gagal menyimpan gambar: {bersihkan_error(e)}", ephemeral=True\n      )\n      return\n  daftar.append({\n      "id": nomor,\n      "waktu": target.isoformat(),\n      "pesan": pesan[:1500],\n      "channel_id": interaction.channel_id,\n      "user_id": interaction.user.id,\n      "guild_id": interaction.guild_id,\n      "gambar": path,\n  })\n  simpan_data()\n  jenis = "server" if interaction.guild_id else "pribadi"\n  tambahan = " dengan gambar" if path else ""\n  await interaction.followup.send(\n      f"Pengingat {jenis}{tambahan} diset untuk {target:%d-%m-%Y %H:%M} WIB"\n      f" (ID {nomor}).",\n      ephemeral=True,\n  )\n\n\n@tree.command(\n    name="listingat",\n    description="Lihat pengingat server ini, atau pengingat pribadi di DM",\n)\nasync def listingat(interaction: discord.Interaction):\n  daftar = gudang_pengingat(interaction.guild_id, interaction.user.id)\n  if not daftar:\n    await interaction.response.send_message(\n        "Tidak ada pengingat aktif.", ephemeral=True\n    )\n    return\n  urut = sorted(\n      daftar,\n      key=lambda p: waktu_pengingat(p) or datetime.max.replace(tzinfo=ZONA_WIB),\n  )\n  baris = []\n  for p in urut:\n    w = waktu_pengingat(p)\n    teks_waktu = f"{w.astimezone(ZONA_WIB):%d-%m-%Y %H:%M}" if w else "?"\n    tanda = " (ada gambar)" if path_gambar_pengingat(p) else ""\n    pembuat = f" oleh <@{p.get(\'user_id\')}>" if interaction.guild_id else ""\n    baris.append(\n        f"`{p.get(\'id\')}` {teks_waktu} WIB{pembuat}{tanda}:"\n        f" {str(p.get(\'pesan\', \'\'))[:80]}"\n    )\n  judul = "Pengingat server ini" if interaction.guild_id else "Pengingat pribadimu"\n  await interaction.response.send_message(\n      (f"{judul}:\\n" + "\\n".join(baris))[:1900],\n      ephemeral=True,\n      allowed_mentions=discord.AllowedMentions.none(),\n  )\n\n\n@tree.command(name="hapusingat", description="Hapus pengingat berdasarkan ID")\n@app_commands.describe(id="ID pengingat dari /listingat")\nasync def hapusingat(interaction: discord.Interaction, id: int):\n  daftar = gudang_pengingat(interaction.guild_id, interaction.user.id)\n  cocok = next((p for p in daftar if p.get("id") == id), None)\n  if cocok is None:\n    await interaction.response.send_message(\n        f"Pengingat {id} tidak ditemukan di sini.", ephemeral=True\n    )\n    return\n  if interaction.guild_id and cocok.get("user_id") != interaction.user.id:\n    izin = getattr(interaction.user, "guild_permissions", None)\n    if not (izin and izin.manage_guild):\n      await interaction.response.send_message(\n          "Kamu hanya bisa menghapus pengingat buatanmu sendiri.",\n          ephemeral=True,\n      )\n      return\n  daftar.remove(cocok)\n  hapus_gambar_pengingat(cocok)\n  simpan_data()\n  await interaction.response.send_message(\n      f"Pengingat {id} berhasil dihapus.", ephemeral=True\n  )\n\n\nSERVER_PRIBADI = [\n    discord.Object(id=1464581081822138370),\n    discord.Object(id=1526640729810800810),\n]\nIZIN_PERINTAH_ADMIN = {\n    "setup": "administrator",\n    "hapussetup": "administrator",\n    "gayanama": "administrator",\n    "pengaturan": "manage_guild",\n    "reset": "administrator",\n    "setwelcome": "administrator",\n    "setbanner": "administrator",\n    "hapusbanner": "administrator",\n    "setautorole": "administrator",\n    "setjoinvoice": "administrator",\n    "colorpanel": "administrator",\n    "stickyset": "administrator",\n    "stickyhapus": "administrator",\n    "setlog": "administrator",\n    "setantispam": "administrator",\n    "purge": "manage_messages",\n    "addcmd": "administrator",\n    "delcmd": "administrator",\n    "hargaset": "administrator",\n    "hargahapus": "administrator",\n    "tiketpanel": "administrator",\n}\n\n\ndef khusus_server(cmd):\n  try:\n    cmd.guild_only = True\n  except AttributeError:\n    pass\n\n\ndef atur_visibilitas_perintah():\n  for nama in PERINTAH_OWNER:\n    cmd = tree.get_command(nama)\n    if cmd is None:\n      continue\n    tree.remove_command(nama)\n    cmd.default_permissions = discord.Permissions(administrator=True)\n    khusus_server(cmd)\n    tree.add_command(cmd, guilds=SERVER_PRIBADI)\n  for nama, izin in IZIN_PERINTAH_ADMIN.items():\n    cmd = tree.get_command(nama)\n    if cmd is None:\n      continue\n    cmd.default_permissions = discord.Permissions(**{izin: True})\n    khusus_server(cmd)\n\n\nasync def sinkron_perintah():\n  try:\n    await tree.sync()\n  except Exception as e:\n    print(f"Sinkron perintah global gagal: {bersihkan_error(e)}")\n  for server in SERVER_PRIBADI:\n    try:\n      await tree.sync(guild=server)\n    except Exception as e:\n      print(f"Sinkron perintah server {server.id} gagal: {bersihkan_error(e)}")\n\n\natur_visibilitas_perintah()\n'

with open(BERKAS, encoding="utf-8") as f:
  teks = f.read()

if "def sinkron_perintah" in teks:
  print("Patch ini sudah pernah dipasang, tidak ada yang diubah.")
  sys.exit(0)

masalah = []

lama_sync = '  await tree.sync()\n  if not getattr(client, "_tugas_latar", False):\n'
baru_sync = '  await sinkron_perintah()\n  if not getattr(client, "_tugas_latar", False):\n'
if teks.count(lama_sync) != 1:
  masalah.append("baris tree.sync di on_ready")

lama_loop = "    asyncio.create_task(loop_perintah_web())\n"
baru_loop = lama_loop + "    asyncio.create_task(loop_pengingat())\n"
if teks.count(lama_loop) != 1:
  masalah.append("baris loop_perintah_web di on_ready")

lama_kantor = (
    '  await interaction.response.send_message(\n'
    '      "Control Room diaktifkan. Tim sedang berdiskusi, mohon tunggu sebentar."\n'
    '  )\n'
)
baru_kantor = (
    '  if interaction.user.id != PEMILIK_ID:\n'
    '    await interaction.response.send_message(\n'
    '        "Perintah ini khusus pemilik bot.", ephemeral=True\n'
    '    )\n'
    '    return\n'
) + lama_kantor
if teks.count(lama_kantor) != 1:
  masalah.append("isi perintah /kantor")

awal_help = teks.find("HELP_KATEGORI = {")
akhir_tanda = "      embed=embed_help_beranda(), view=HelpView(), ephemeral=True\n  )\n"
akhir_help = teks.find(akhir_tanda)
if awal_help < 0 or akhir_help < awal_help or teks.count(akhir_tanda) != 1:
  masalah.append("bagian /help")

tanda_ekstensi = "\nmuat_semua_ekstensi()\n"
if teks.count(tanda_ekstensi) != 1:
  masalah.append("baris muat_semua_ekstensi")

for nama in ("ingatkan", "listingat", "hapusingat"):
  if f'name="{nama}"' in teks:
    masalah.append(f"perintah /{nama} sudah ada di bot.py")

if masalah:
  print("Dibatalkan, tidak ada yang diubah. Titik yang tidak cocok:")
  for m in masalah:
    print("-", m)
  sys.exit(1)

teks = teks.replace(lama_sync, baru_sync)
teks = teks.replace(lama_loop, baru_loop)
teks = teks.replace(lama_kantor, baru_kantor)
awal_help = teks.find("HELP_KATEGORI = {")
akhir_help = teks.find(akhir_tanda) + len(akhir_tanda)
teks = teks[:awal_help] + HELP_BARU + teks[akhir_help:]
teks = teks.replace(tanda_ekstensi, "\n" + BLOK_BAWAH + "\n" + tanda_ekstensi)

try:
  compile(teks, BERKAS, "exec")
except SyntaxError as e:
  print(f"Dibatalkan, hasil patch tidak valid di baris {e.lineno}.")
  sys.exit(1)

with open(BERKAS, "w", encoding="utf-8") as f:
  f.write(teks)
print("Selesai. Perintah owner disembunyikan, perintah admin dibatasi, /help difilter, pengingat per server dan DM aktif.")
